const AUTH_BASE_URL = 'http://localhost:8081/auth';
const API_BASE_URL = 'http://localhost:8080'; // întrebări, răspunsuri etc.

async function request(path, options = {}) {
  // Alege baza URL în funcție de prefix
  const baseUrl = path.startsWith('/auth') || path === '/login' || path === '/register'
    ? AUTH_BASE_URL
    : API_BASE_URL;

  let headers = {
    'Content-Type': 'application/json',
    ...options.headers,
  };

  // Adaugă token-ul pentru endpoint-urile API de pe 8080, cu excepția celui de listare răspunsuri publice
  if (baseUrl === API_BASE_URL && !path.startsWith('/answers/question/')) {
      const token = localStorage.getItem('token');
      if (token) {
          headers = { ...headers, Authorization: `Bearer ${token}` };
      }
  } else if (baseUrl === AUTH_BASE_URL) {
       // Potențial, adaugă token și pentru endpoint-uri de auth dacă e cazul (ex: refresh token)
       // Momentan, auth endpoints like login/register don't need token
  }


  const response = await fetch(`${baseUrl}${path}`, {
    credentials: 'include',
    headers,
    ...options,
  });

  if (!response.ok) {
  const contentType = response.headers.get('content-type') || '';
  let errMsg = `Request failed: ${response.status}`;

  try {
    if (contentType.includes('application/json')) {
      const errJson = await response.clone().json(); // ✅ clone pentru JSON
      errMsg = errJson.message || errMsg;
    } else {
      const errText = await response.clone().text(); // ✅ clone pentru text
      errMsg = errText || errMsg;
    }
  } catch (e) {
    console.error("Eroare la parsarea răspunsului:", e);
  }

  throw new Error(errMsg);
}


